package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.repository.articles.JdbcEntityAnalysisState;
import com.lianxibu.site.service.articles.EntityAnalysisStateService;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;

/** Real first-judgment/entity CAS/intent atomic writes. New model values remain explicit fictional validated values. */
class CatalogVersionJudgmentWriterTest extends CatalogVersionJudgmentValueTest {
    CatalogVersionCommitPermitService guard(){return new CatalogVersionCommitPermitService(f.source,f.tx,f.category);}
    CatalogVersionCommitPermitService.Captured capture(CatalogVersionCommitPermitService guard){return guard.capture("fictional-entity","fictional-analysis","fictional-current-item",f.clock.instant()).orElseThrow();}
    CatalogVersionJudgmentValue.Value value(CatalogVersionCommitPermitService.Captured c,boolean recommend){var p=c.projection();var i=input(p);return CatalogVersionJudgmentValue.create(p,i,result(i,payload(p,recommend))).orElseThrow();}
    CatalogVersionJudgmentWriter writer(CatalogVersionCommitPermitService guard){return new CatalogVersionJudgmentWriter(f.source,guard,new EntityAnalysisStateService(new JdbcEntityAnalysisState(f.source)),f.category,f.clock);}
    CatalogVersionJudgmentLedger.Stored apply(CatalogVersionJudgmentWriter writer,CatalogVersionJudgmentValue.Value value,CatalogVersionCommitPermitService.Captured c){return f.writes.execute(new SharedWriteExecutor.ActionContext(JdbcCatalogVersionJudgments.action(value.judgmentKey()),JdbcCatalogVersionJudgments.id(value.judgmentKey()),value.hash()),k->writer.committed(value.judgmentKey()),a->writer.applyInTransaction(value,c));}
    @Test void FourCategoriesAllocateOneNativeGenerationAndOriginalLogicalIntentWithoutNewBudget(){for(String cat:List.of("agent","skill","workflow","model")){initialize(cat,false);var guard=guard();var c=capture(guard);var v=value(c,true);var writer=writer(guard);var stored=apply(writer,v,c);assertEquals("reanalyze",stored.verdict());assertEquals(2L,stored.generation());assertEquals(2,f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals("queued",f.jdbc.queryForObject("SELECT analysis_state FROM analyzed_entities",String.class));var intent=new JdbcJobRecords(f.source).byId(stored.intentId());assertEquals("generation_intent",intent.kind());assertEquals("fictional-analysis-key",intent.logicalKey());assertEquals(2L,intent.generation());assertEquals(0,intent.callCount());assertNull(intent.maxAttempts());assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE record_kind='logical_task'",Integer.class));assertEquals(1,f.sends);assertEquals(stored.json(),apply(writer,v,null).json());assertEquals(2,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE record_kind='generation_intent'",Integer.class));}}
    @Test void FirstFalseOrDeclinedWinsAgainstLaterRecommendationAndChangedCurrentProof(){for(boolean unchanged:List.of(false,true)){initialize("agent",false);if(unchanged){current=f.catalogPayload();update();}var guard=guard();var c=capture(guard);var v=value(c,false);var writer=writer(guard);var stored=apply(writer,v,c);assertEquals(unchanged?"unchanged":"changed_declined",stored.verdict());assertNull(stored.generation());assertEquals(1,f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));if(!unchanged){var later=value(c,true);current.put("summary","Fictional later metadata");update();assertEquals(stored.json(),apply(writer,later,null).json());}assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE record_kind='generation_intent'",Integer.class));assertEquals(1,f.sends);}}
    @Test void FailureAfterReservationRollsBackEntityIntentAndPermanentDecisionTogether(){var guard=guard();var c=capture(guard);var v=value(c,true);var writer=writer(guard);long revision=f.jdbc.queryForObject("SELECT revision FROM analyzed_entities",Long.class);f.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_judgment_append_failure CHECK(target_type IS NULL OR target_type<>'catalog_version_judgment')");assertThrows(RuntimeException.class,()->apply(writer,v,c));assertEquals(1,f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(revision,f.jdbc.queryForObject("SELECT revision FROM analyzed_entities",Long.class));assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE record_kind='generation_intent'",Integer.class));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='catalog_version_judgment'",Integer.class));f.jdbc.execute(mysql()?"ALTER TABLE jobs DROP CHECK fictional_judgment_append_failure":"ALTER TABLE jobs DROP CONSTRAINT fictional_judgment_append_failure");assertEquals(2L,apply(writer,v,c).generation());}
    @Test void MissingForeignOrChangedFreshPermitRejectsBeforeAnyGenerationMutation(){var guard=guard();var c=capture(guard);var v=value(c,true);assertThrows(RuntimeException.class,()->apply(writer(guard),v,null));assertThrows(RuntimeException.class,()->apply(writer(guard()),v,c));current.put("summary","Fictional changed");update();assertThrows(RuntimeException.class,()->apply(writer(guard),v,c));assertEquals(1,f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='catalog_version_judgment'",Integer.class));assertEquals(1,f.sends);}
    @Test void OriginalCommittedAckUnknownReadsPermanentDecisionWithoutReservingAgain(){var guard=guard();var c=capture(guard);var v=value(c,true);var writer=writer(guard);f.tx.ackLost=true;var stored=apply(writer,v,c);assertEquals(2L,stored.generation());assertEquals(stored.json(),apply(writer,v,null).json());assertEquals(2,f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='catalog_version_judgment'",Integer.class));assertEquals(1,f.sends);}
    void NativeConcurrentSameVersionCallersReturnOneOriginalJudgmentAndGeneration()throws Exception{var guard=guard();var c=capture(guard);var v=value(c,true);var writer=writer(guard);var start=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){var first=pool.submit(()->{start.await();return apply(writer,v,c);});var second=pool.submit(()->{start.await();return apply(writer,v,c);});start.countDown();assertEquals(first.get(10,TimeUnit.SECONDS).json(),second.get(10,TimeUnit.SECONDS).json());assertEquals(2,f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(2,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE record_kind='generation_intent'",Integer.class));assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='catalog_version_judgment'",Integer.class));assertEquals(1,f.sends);}}
}
